namespace sv_b4928119870f45e598eafd0be17af4c7.Services;

public class DoctorInfo
{
    public string Name { get; set; } = "";
    public bool AcceptsSelfPay { get; set; }
}

public class ValidationResult
{
    public bool IsValid => Errors.Count == 0;
    public Dictionary<string, List<string>> Errors { get; set; } = new();
}

public class AppointmentService
{
    private static readonly List<DoctorInfo> Doctors =
    [
        new() { Name = "Dr. Smith", AcceptsSelfPay = false },
        new() { Name = "Dr. Johnson", AcceptsSelfPay = true },
        new() { Name = "Dr. Patel", AcceptsSelfPay = true },
        new() { Name = "Dr. Lee", AcceptsSelfPay = false },
    ];

    private static readonly List<string> TakenSlots = ["10:00 AM"];

    public Task<List<DoctorInfo>> GetDoctorsAsync()
    {
        return Task.FromResult(Doctors);
    }

    public Task<List<string>> GetAvailableSlotsAsync(string doctor, DateOnly date)
    {
        // Stub: return fixed slots regardless of doctor/date
        List<string> slots =
        [
            "9:00 AM", "10:00 AM", "11:00 AM",
            "1:00 PM", "2:00 PM", "3:00 PM", "4:00 PM"
        ];
        return Task.FromResult(slots);
    }

    public Task<ValidationResult> ValidatePatientAsync(
        string email, string insuranceProvider, string doctor, string timeSlot)
    {
        var result = new ValidationResult();

        if (string.Equals(email, "taken@example.com", StringComparison.OrdinalIgnoreCase))
        {
            result.Errors.GetOrAdd(nameof(AppointmentModel.Email), [])
                .Add("Account has outstanding balance");
        }

        if (string.Equals(insuranceProvider, "None", StringComparison.Ordinal))
        {
            var doc = Doctors.FirstOrDefault(d => d.Name == doctor);
            if (doc is { AcceptsSelfPay: false })
            {
                result.Errors.GetOrAdd(nameof(AppointmentModel.Doctor), [])
                    .Add("Selected doctor does not accept self-pay patients");
            }
        }

        if (TakenSlots.Contains(timeSlot, StringComparer.OrdinalIgnoreCase))
        {
            result.Errors.GetOrAdd(nameof(AppointmentModel.TimeSlot), [])
                .Add("This slot is no longer available");
        }

        return Task.FromResult(result);
    }
}

internal static class DictionaryExtensions
{
    public static TValue GetOrAdd<TKey, TValue>(
        this Dictionary<TKey, TValue> dict, TKey key, TValue defaultValue) where TKey : notnull
    {
        if (!dict.TryGetValue(key, out var value))
        {
            value = defaultValue;
            dict[key] = value;
        }
        return value;
    }
}

using System.ComponentModel.DataAnnotations;

namespace sv_b4928119870f45e598eafd0be17af4c7.Services;

public class AppointmentModel
{
    [Required(ErrorMessage = "Patient name is required.")]
    public string? PatientName { get; set; }

    [Required(ErrorMessage = "Email is required.")]
    [EmailAddress(ErrorMessage = "Enter a valid email address.")]
    public string? Email { get; set; }

    [Required(ErrorMessage = "Phone is required.")]
    [Phone(ErrorMessage = "Enter a valid phone number.")]
    public string? Phone { get; set; }

    [Required(ErrorMessage = "Insurance provider is required.")]
    public string? InsuranceProvider { get; set; }

    [Required(ErrorMessage = "Please select a doctor.")]
    public string? Doctor { get; set; }

    [Required(ErrorMessage = "Date is required.")]
    [FutureDate(ErrorMessage = "Date must be in the future.")]
    public DateOnly? AppointmentDate { get; set; }

    [Required(ErrorMessage = "Please select a time slot.")]
    public string? TimeSlot { get; set; }

    [Required(ErrorMessage = "Reason for visit is required.")]
    [MaxLength(500, ErrorMessage = "Reason must be 500 characters or fewer.")]
    public string? ReasonForVisit { get; set; }
}

public class FutureDateAttribute : ValidationAttribute
{
    public override bool IsValid(object? value)
    {
        if (value is DateOnly date)
        {
            return date > DateOnly.FromDateTime(DateTime.Today);
        }
        return value is null; // Let [Required] handle nulls
    }
}

using Microsoft.AspNetCore.Components;
using Microsoft.AspNetCore.Components.Forms;

namespace sv_b4928119870f45e598eafd0be17af4c7.Components;

public class CustomValidator : ComponentBase
{
    [CascadingParameter]
    private EditContext? EditContext { get; set; }

    private ValidationMessageStore? messageStore;

    protected override void OnInitialized()
    {
        messageStore = new ValidationMessageStore(EditContext!);
        EditContext!.OnValidationRequested += (s, e) => messageStore.Clear();
        EditContext!.OnFieldChanged += (s, e) => messageStore.Clear(e.FieldIdentifier);
    }

    public void DisplayErrors(Dictionary<string, List<string>> errors)
    {
        foreach (var (field, messages) in errors)
        {
            foreach (var message in messages)
            {
                messageStore!.Add(EditContext!.Field(field), message);
            }
        }
        EditContext!.NotifyValidationStateChanged();
    }

    public void ClearErrors()
    {
        messageStore?.Clear();
        EditContext?.NotifyValidationStateChanged();
    }
}

@page "/book-appointment"
@rendermode InteractiveServer
@using sv_b4928119870f45e598eafd0be17af4c7.Services
@inject AppointmentService AppointmentService

<PageTitle>Book Appointment</PageTitle>

<h3>Book an Appointment</h3>

<EditForm EditContext="editContext" OnSubmit="HandleSubmit" FormName="book-appointment">
    <DataAnnotationsValidator />
    <CustomValidator @ref="customValidator" />

    <h4>Step 1: Patient Information</h4>

    <div class="mb-3">
        <label class="form-label">Patient Name</label>
        <InputText class="form-control" @bind-Value="Model.PatientName" />
        <ValidationMessage For="() => Model.PatientName" />
    </div>

    <div class="mb-3">
        <label class="form-label">Email</label>
        <InputText class="form-control" @bind-Value="Model.Email" />
        <ValidationMessage For="() => Model.Email" />
    </div>

    <div class="mb-3">
        <label class="form-label">Phone</label>
        <InputText class="form-control" @bind-Value="Model.Phone" />
        <ValidationMessage For="() => Model.Phone" />
    </div>

    <div class="mb-3">
        <label class="form-label">Insurance Provider</label>
        <InputSelect class="form-select" @bind-Value="Model.InsuranceProvider">
            <option value="">-- Select --</option>
            <option value="Aetna">Aetna</option>
            <option value="BlueCross">BlueCross</option>
            <option value="Cigna">Cigna</option>
            <option value="UnitedHealth">UnitedHealth</option>
            <option value="None">None</option>
        </InputSelect>
        <ValidationMessage For="() => Model.InsuranceProvider" />
    </div>

    @if (!showStep2)
    {
        <button type="button" class="btn btn-primary" @onclick="ProceedToStep2" disabled="@isProcessing">
            @(isProcessing ? "Validating..." : "Continue to Step 2")
        </button>
    }

    @if (showStep2)
    {
        <hr />
        <h4>Step 2: Appointment Details</h4>

        <div class="mb-3">
            <label class="form-label">Preferred Doctor</label>
            <InputSelect class="form-select" @bind-Value="Model.Doctor" @bind-Value:after="OnDoctorOrDateChanged">
                <option value="">-- Select --</option>
                @foreach (var doc in doctors)
                {
                    <option value="@doc.Name">@doc.Name</option>
                }
            </InputSelect>
            <ValidationMessage For="() => Model.Doctor" />
        </div>

        <div class="mb-3">
            <label class="form-label">Date</label>
            <InputDate class="form-control" @bind-Value="Model.AppointmentDate" @bind-Value:after="OnDoctorOrDateChanged" />
            <ValidationMessage For="() => Model.AppointmentDate" />
        </div>

        <div class="mb-3">
            <label class="form-label">Time Slot</label>
            <InputSelect class="form-select" @bind-Value="Model.TimeSlot">
                <option value="">-- Select --</option>
                @foreach (var slot in availableSlots)
                {
                    <option value="@slot">@slot</option>
                }
            </InputSelect>
            <ValidationMessage For="() => Model.TimeSlot" />
        </div>

        <div class="mb-3">
            <label class="form-label">Reason for Visit</label>
            <InputTextArea class="form-control" @bind-Value="Model.ReasonForVisit" rows="3" />
            <ValidationMessage For="() => Model.ReasonForVisit" />
        </div>

        <button type="button" class="btn btn-secondary me-2" @onclick="BackToStep1">Back</button>
        <button type="button" class="btn btn-primary me-2" @onclick="CheckAvailability" disabled="@isProcessing">
            @(isProcessing ? "Checking..." : "Check Availability")
        </button>
        <button type="submit" class="btn btn-success" disabled="@(!isAvailabilityConfirmed || isProcessing)">
            Confirm Appointment
        </button>
    }
</EditForm>

@if (isSubmitted)
{
    <div class="alert alert-success mt-3">Appointment booked successfully!</div>
}

@code {
    private EditContext editContext = default!;
    private CustomValidator? customValidator;
    private AppointmentModel Model = new();

    private List<DoctorInfo> doctors = [];
    private List<string> availableSlots = [];

    private bool showStep2;
    private bool isProcessing;
    private bool isAvailabilityConfirmed;
    private bool isSubmitted;

    // Step 1 field names for partial validation
    private static readonly string[] Step1Fields =
        [nameof(AppointmentModel.PatientName), nameof(AppointmentModel.Email),
         nameof(AppointmentModel.Phone), nameof(AppointmentModel.InsuranceProvider)];

    protected override async Task OnInitializedAsync()
    {
        editContext = new EditContext(Model);
        doctors = await AppointmentService.GetDoctorsAsync();
    }

    private void ProceedToStep2()
    {
        // Validate only step 1 fields
        editContext.Validate();
        var hasStep1Errors = Step1Fields.Any(f =>
            editContext.GetValidationMessages(editContext.Field(f)).Any());

        if (!hasStep1Errors)
        {
            showStep2 = true;
        }
    }

    private async Task OnDoctorOrDateChanged()
    {
        isAvailabilityConfirmed = false;
        if (!string.IsNullOrEmpty(Model.Doctor) && Model.AppointmentDate.HasValue)
        {
            availableSlots = await AppointmentService.GetAvailableSlotsAsync(
                Model.Doctor, Model.AppointmentDate.Value);
            Model.TimeSlot = null;
        }
    }

    private async Task CheckAvailability()
    {
        customValidator?.ClearErrors();
        isAvailabilityConfirmed = false;

        // Full form validation first
        if (!editContext.Validate())
        {
            return;
        }

        isProcessing = true;
        try
        {
            var result = await AppointmentService.ValidatePatientAsync(
                Model.Email!, Model.InsuranceProvider!, Model.Doctor!, Model.TimeSlot!);

            if (!result.IsValid)
            {
                customValidator!.DisplayErrors(result.Errors);
                return;
            }

            isAvailabilityConfirmed = true;
        }
        finally
        {
            isProcessing = false;
        }
    }

    private void BackToStep1()
    {
        showStep2 = false;
        isAvailabilityConfirmed = false;
    }

    private void HandleSubmit()
    {
        if (isAvailabilityConfirmed && editContext.Validate())
        {
            isSubmitted = true;
        }
    }
}

